using Validator = std::function<bool(const Request&)>;

class Ingress {
    std::vector<Validator> rules_;
public:
    void add(Validator v) { rules_.push_back(std::move(v)); }
    bool accept(const Request& r) const {
        for (const auto& rule : rules_)
            if (!rule(r)) return false;   // short-circuit: handler not reached
        return true;
    }
};
